package com.lumira.platform.identity;
import com.lumira.platform.common.ClientAddressResolver;
import com.lumira.platform.identity.api.MaintenancePolicyPort;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.security.web.access.intercept.AuthorizationFilter;
import org.springframework.context.annotation.*;
import org.springframework.http.MediaType;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.csrf.HttpSessionCsrfTokenRepository;
@Configuration
public class SecurityConfiguration {
 private static void json(HttpServletResponse response,int status,String body)throws java.io.IOException{response.setStatus(status);response.setContentType(MediaType.APPLICATION_JSON_VALUE);response.setCharacterEncoding("UTF-8");response.getWriter().write(body);}
 @Bean SecurityFilterChain security(HttpSecurity http,JdbcClient jdbc,LoginRateLimiter limiter,LoginAudit loginAudit,ClientAddressResolver addresses,MaintenancePolicyPort maintenance)throws Exception{
  http.authorizeHttpRequests(auth->auth
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/feedback/manage","/api/feedback/manage/*").hasAuthority("platform:feedback:manage")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/feedback/manage/*").hasAuthority("platform:feedback:manage")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/feedback/images/*").hasAnyAuthority("platform:feedback:read","platform:feedback:manage")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/feedback/images").hasAuthority("platform:feedback:create")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/feedback","/api/feedback/*").hasAuthority("platform:feedback:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/feedback").hasAuthority("platform:feedback:create")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/account/drafts","/api/account/drafts/*").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/account/drafts/*").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/account/drafts/*").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/account/security-events").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/account/notifications","/api/account/notifications/unread-count").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/account/notifications/*/read","/api/account/notifications/read-all").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/auth/password-recovery/request","/api/auth/password-recovery/confirm").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/auth/passkeys/authentication/availability").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/auth/passkeys/authentication/options","/api/auth/passkeys/authentication/complete").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/auth/passkeys/registration/options","/api/auth/passkeys/registration/complete").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/auth/passkeys").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.PATCH,"/api/auth/passkeys/*").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/auth/passkeys/*").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/account/email").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/account/email/request","/api/account/email/confirm").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/account/phone").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/account/phone/request","/api/account/phone/confirm").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/mail-deliveries").hasAuthority("platform:audit:read")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/sms-deliveries").hasAuthority("platform:audit:read")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/event-outbox").hasAuthority("platform:audit:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/event-outbox/*/replay").hasAuthority("platform:events:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/monitoring/summary").hasAuthority("platform:audit:read")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/sensitive-words","/api/platform/sensitive-words/*").hasAuthority("platform:sensitive-words:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/sensitive-words/check").hasAuthority("platform:sensitive-words:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/sensitive-words/import").hasAuthority("platform:sensitive-words:import")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/sensitive-words").hasAuthority("platform:sensitive-words:write")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/sensitive-words/*").hasAuthority("platform:sensitive-words:write")
    .requestMatchers(org.springframework.http.HttpMethod.PATCH,"/api/platform/sensitive-words/*/status").hasAuthority("platform:sensitive-words:write")
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/platform/sensitive-words/*").hasAuthority("platform:sensitive-words:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/localization/entries","/api/platform/localization/entries/*","/api/platform/localization/locales").hasAuthority("platform:localization:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/localization/entries").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/localization/entries/*").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.PATCH,"/api/platform/localization/entries/*/status").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/platform/localization/entries/*").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/localization/import").hasAuthority("platform:localization:import")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/localization/translations").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/platform/localization/translations/*").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/localization/bundle/preview","/api/platform/localization/bundle/import").hasAuthority("platform:localization:import")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/localization/ai/providers").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/localization/ai/translate").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/localization/publish/*").hasAuthority("platform:localization:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/public/localization/bundle/*","/api/public/localization/locales").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/navigation").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/navigation/menus","/api/platform/navigation/menus/*").hasAuthority("platform:navigation:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/navigation/menus").hasAuthority("platform:navigation:write")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/navigation/menus/*","/api/platform/navigation/menus/reorder").hasAuthority("platform:navigation:write")
    .requestMatchers(org.springframework.http.HttpMethod.PATCH,"/api/platform/navigation/menus/*/status").hasAuthority("platform:navigation:write")
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/platform/navigation/menus/*").hasAuthority("platform:navigation:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/online-users").hasAuthority("platform:users:read")
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/platform/online-users/*","/api/platform/online-users/user/*").hasAuthority("platform:users:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/files","/api/platform/files/*","/api/platform/files/*/content").hasAuthority("platform:files:read")
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/platform/files/*","/api/platform/files/*/purge").hasAuthority("platform:files:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/files/*/restore").hasAuthority("platform:files:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/notifications").hasAuthority("platform:notifications:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/notifications").hasAuthority("platform:notifications:write")
    .dispatcherTypeMatchers(jakarta.servlet.DispatcherType.ERROR).permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/account/profile-fields").authenticated()
    .requestMatchers("/api/account/profile-values","/api/account/profile-completion").authenticated()
    .requestMatchers("/api/account/files","/api/account/files/*","/api/account/files/*/content","/api/account/files/*/restore","/api/account/files/*/purge").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/account/files/*/preview").authenticated()
    .requestMatchers("/api/account/avatar","/api/account/avatar/content").authenticated()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/*/history","/api/platform/settings/*/history/*").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/settings/*/rollback").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/smtp").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/smtp").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/settings/smtp/test").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/sms").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/sms").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/settings/sms/test").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/security").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/security").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/passkey").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/passkey").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/profile-fields").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/profile-fields").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/public/maintenance").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/maintenance","/api/platform/settings/maintenance/roles").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/maintenance").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/public/watermark").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/watermark").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/watermark").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/public/agreements").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/agreements").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/agreements").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/public/branding").permitAll()
    .requestMatchers("/api/auth/csrf","/api/auth/login","/actuator/health","/actuator/health/**").permitAll()
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/organizations/*/ancestors","/api/platform/organizations","/api/platform/organizations/*","/api/platform/users/*/organizations").hasAuthority("platform:organizations:read")
    .requestMatchers("/api/platform/organizations","/api/platform/organizations/*","/api/platform/users/*/organizations").hasAuthority("platform:organizations:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/branding").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/branding").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/settings/file-retention").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/settings/file-retention").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/ai/providers","/api/platform/ai/capabilities").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/ai/providers/*/models").hasAuthority("platform:settings:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/ai/providers/discover-models").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/ai/providers","/api/platform/ai/providers/*/test","/api/platform/ai/judgments").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/ai/providers/*").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.DELETE,"/api/platform/ai/providers/*").hasAuthority("platform:settings:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/ai/chat").hasAuthority("platform:users:read")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/ai/actions/*/confirm").hasAuthority("platform:users:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/dictionaries/*/export","/api/platform/dictionaries/*/items/*/ancestors","/api/platform/dictionaries","/api/platform/dictionaries/*","/api/platform/dictionaries/*/items","/api/platform/dictionaries/*/items/*").hasAuthority("platform:dictionaries:read")
    .requestMatchers("/api/platform/dictionaries","/api/platform/dictionaries/*","/api/platform/dictionaries/*/items","/api/platform/dictionaries/*/items/*").hasAuthority("platform:dictionaries:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/audit").hasAuthority("platform:audit:read")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/modules","/api/platform/modules/*/history").hasAuthority("platform:modules:read")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/modules/packages","/api/platform/modules/*/packages").hasAuthority("platform:modules:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/modules/*/state").hasAuthority("platform:modules:write")
    .requestMatchers(org.springframework.http.HttpMethod.POST,"/api/platform/modules/packages","/api/platform/modules/packages/*/activate","/api/platform/modules/packages/*/reject").hasAuthority("platform:modules:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/roles","/api/platform/roles/*","/api/platform/permissions","/api/platform/users/*/roles").hasAuthority("platform:roles:read")
    .requestMatchers("/api/platform/roles","/api/platform/roles/*","/api/platform/users/*/roles").hasAuthority("platform:roles:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/users/*/file-quota").hasAuthority("platform:users:read")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/users/*/file-quota/preview").hasAuthority("platform:roles:read")
    .requestMatchers(org.springframework.http.HttpMethod.PUT,"/api/platform/users/*/editor").hasAnyAuthority("platform:users:write","platform:roles:write","platform:organizations:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/platform/users","/api/platform/users/export","/api/platform/users/*").hasAuthority("platform:users:read")
    .requestMatchers("/api/platform/users","/api/platform/users/*").hasAuthority("platform:users:write")
    .requestMatchers(org.springframework.http.HttpMethod.GET,"/api/dictionaries/*/items","/api/dictionaries/*/items/*").authenticated()
    .requestMatchers("/api/auth/me","/api/auth/logout","/api/account/password","/api/account/profile","/api/account/sessions","/api/account/sessions/*").authenticated()
    .anyRequest().denyAll())
   .csrf(csrf->csrf.csrfTokenRepository(new HttpSessionCsrfTokenRepository()))
   .requestCache(cache->cache.disable())
   .formLogin(form->form.loginProcessingUrl("/api/auth/login")
    .successHandler((req,res,auth)->{
     if(!maintenance.canLogin(auth.getName())){org.springframework.security.core.context.SecurityContextHolder.clearContext();var session=req.getSession(false);if(session!=null)session.invalidate();json(res,503,"{\"detail\":\"maintenanceActive\"}");return;}
     try{loginAudit.record(auth.getName(),true,addresses.resolve(req),req.getHeader("User-Agent"));}catch(RuntimeException unavailable){org.springframework.security.core.context.SecurityContextHolder.clearContext();var session=req.getSession(false);if(session!=null)session.invalidate();json(res,503,"{\"detail\":\"unavailable\"}");return;}
     json(res,200,"{\"authenticated\":true}");
    })
    .failureHandler((req,res,error)->{loginAudit.record(req.getParameter("username"),false,addresses.resolve(req),req.getHeader("User-Agent"));json(res,401,"{\"detail\":\"用户名或密码错误\"}");}))
   .logout(logout->logout.logoutUrl("/api/auth/logout").deleteCookies("LUMIRA_NEXT_SESSION")
    .logoutSuccessHandler((req,res,auth)->res.setStatus(204)))
   .exceptionHandling(errors->errors
    .authenticationEntryPoint((req,res,error)->json(res,401,"{\"detail\":\"请先登录\"}"))
    .accessDeniedHandler((req,res,error)->json(res,403,"{\"detail\":\"无权访问或安全令牌已过期\"}")));
  http.addFilterBefore(new LoginRateLimitFilter(limiter,addresses,loginAudit), org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter.class);
  http.addFilterBefore(new CurrentAuthorityFilter(jdbc), AuthorizationFilter.class);
  return http.build();
 }
}
